#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);   // если не стартует — попробуйте 0x3F

// Пользовательский символ "№" (слот 1), 5x8
static const uint8_t NO_SIGN[8] = {
  0b10111,
  0b11111,
  0b11100,
  0b10100,
  0b10111,
  0b00000,
  0b00000,
  0b00000
};

// \x01 — код нашего пользовательского символа.
// ВАЖНО: строка склеена из двух литералов, иначе "\x011"
// скушается как один hex-escape 0x11!
static const char MSG[] = "Misha Lentyai \x01" "1  ***  ";
static const uint8_t LEN = sizeof(MSG) - 1;

const uint16_t STEP_MS = 300;   // скорость прокрутки
uint8_t  pos = 0;
uint32_t tPrev = 0;

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.createChar(1, NO_SIGN);
  lcd.clear();
}

void loop() {
  uint32_t now = millis();
  if (now - tPrev >= STEP_MS) {
    tPrev = now;
    lcd.setCursor(0, 0);
    for (uint8_t i = 0; i < 16; i++)
      lcd.write((uint8_t)MSG[(pos + i) % LEN]);  // циклический сдвиг
    if (++pos >= LEN) pos = 0;
  }
}
